  world=page.evaluate('JSON.parse(localStorage.getItem("saguk-studio.world.v1")).world');assert [sum(t['ownerId']==c['id'] for t in world['territories']) for c in world['countries']]==[41,32,42,14,11,16,4];assert world['countries'][0]['capitalId']=='territory-003';assert len(world['deployment']['generals'])==23
  assert page.locator('[data-action=territory-v25]').count()==0;page.screenshot(path=str(ROOT/f'docs/v25-{label}-borders.png'));page.locator('nav [data-page=deployment]').click();expect(page.locator('#deployment-person')).to_be_visible();page.screenshot(path=str(ROOT/f'docs/v25-{label}-deployment.png'))
