  page.locator('[data-action=territory-v25]').click();page.locator('nav [data-page=simulation]').click();page.locator('[data-action=new-run]').click();page.locator('#dialog-form button[type=submit]').click();assert page.evaluate('JSON.parse(localStorage.getItem("saguk-studio.completed-run.v11")).engineState.capitals[0]')==2
