 # Render native decoded MP3 through the actual mixer and compressor, not a mock gain implementation.
 page=browser.new_page();page.on('pageerror',lambda e:errors.append(str(e)));page.goto('http://127.0.0.1:3000/',wait_until='networkidle')
 measurement=page.evaluate('''async()=>{const {SoundMixer}=await import('/src/audio/mixer.js'),{SOUND_PACK}=await import('/src/data/sound-art.js');const results=[];class Offline extends OfflineAudioContext{get state(){return 'running';}}async function render(ids,volume){const seconds=Math.max(...ids.map(id=>SOUND_PACK.find(s=>s.id===id).duration))+.1,ctx=new Offline(2,Math.ceil(seconds*44100),44100),m=new SoundMixer({settings:{volume},contextFactory:()=>ctx,now:()=>0});m.prime=()=>{};await m.unlock();for(const id of ids)if(!await m.play({id,group:'battle',priority:40}))throw Error('Not started: '+id);const b=await ctx.startRendering();let peak=0,energy=0,count=0;for(let ch=0;ch<b.numberOfChannels;ch++)for(const n of b.getChannelData(ch)){peak=Math.max(peak,Math.abs(n));energy+=n*n;count++;}return {peak,rms:Math.sqrt(energy/count)};}for(const s of SOUND_PACK){const r=await render([s.id],.5);if(r.peak<.001||r.peak>=1)throw Error(s.id+' invalid native output '+r.peak);results.push({id:s.id,...r});}const combined=await render(['dice_roll_wood_alt','dice_roll','battle_impact','capital_fall'],1);return {clips:results.length,minPeak:Math.min(...results.map(r=>r.peak)),maxPeak:Math.max(...results.map(r=>r.peak)),combined};}''')
 assert measurement['clips']==42 and measurement['combined']['peak']<1,measurement
 (ROOT/'.artifacts/v25-native-audio.json').write_text(json.dumps(measurement,indent=2));print('PASS native 42-clip balanced output and maximum-volume four-source mix:',measurement,flush=True)
 assert not errors,errors;assert not failed,failed;browser.close();print('PASS JavaScript errors/request failures: 0',flush=True)
